function compressAvatarFile(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Avatar could not be read."));
    reader.onload = () => {
      const image = new Image();
      image.onerror = () => reject(new Error("Avatar could not be decoded."));
      image.onload = () => {
        const maxDimension = 1600;
        const scale = Math.min(1, maxDimension / Math.max(image.naturalWidth, image.naturalHeight));
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
        canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
        const context = canvas.getContext("2d");
        if (!context) return reject(new Error("Avatar compression is unavailable."));
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/webp", .8));
      };
      image.src = String(reader.result || "");
    };
    reader.readAsDataURL(file);
  });
}

function GoldParticleField() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => { const canvas = canvasRef.current; if (!canvas) return; const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches; const ctx = canvas.getContext("2d"); if (!ctx) return; let frame = 0; let particleColor = "242, 209, 138"; const updateParticleTheme = () => { particleColor = document.documentElement.classList.contains("dark") ? "242, 209, 138" : "138, 97, 30"; }; updateParticleTheme(); const themeObserver = new MutationObserver(updateParticleTheme); themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] }); let particles: Array<{ x: number; y: number; r: number; a: number; vx: number; vy: number }> = []; const resize = () => { const ratio = Math.min(window.devicePixelRatio || 1, 1.5); canvas.width = window.innerWidth * ratio; canvas.height = window.innerHeight * ratio; canvas.style.width = `${window.innerWidth}px`; canvas.style.height = `${window.innerHeight}px`; ctx.setTransform(ratio, 0, 0, ratio, 0, 0); particles = Array.from({ length: Math.min(46, Math.floor(window.innerWidth / 28)) }, (_, i) => ({ x: (i * 83) % window.innerWidth, y: (i * 137) % window.innerHeight, r: 0.6 + (i % 3) * 0.35, a: 0.12 + (i % 5) * 0.04, vx: 0.02 + (i % 4) * 0.008, vy: -0.05 - (i % 3) * 0.012 })); }; resize(); window.addEventListener("resize", resize); const draw = () => { ctx.clearRect(0, 0, window.innerWidth, window.innerHeight); particles.forEach((p) => { ctx.beginPath(); ctx.fillStyle = `rgba(${particleColor}, ${p.a})`; ctx.shadowBlur = 8; ctx.shadowColor = `rgba(${particleColor}, .38)`; ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill(); if (!reduced) { p.x += p.vx; p.y += p.vy; if (p.y < -8) p.y = window.innerHeight + 8; if (p.x > window.innerWidth + 8) p.x = -8; } }); if (!reduced) frame = requestAnimationFrame(draw); }; draw(); return () => { cancelAnimationFrame(frame); window.removeEventListener("resize", resize); themeObserver.disconnect(); }; }, []);
  return <canvas ref={canvasRef} className="gold-particle-canvas" aria-hidden="true" />;
}

function ScrambleText({ text, className = "" }: { text: string; className?: string }) {
  const [display, setDisplay] = useState(text);
  const timerRef = useRef<number | null>(null);
  const run = () => { if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return; if (timerRef.current) window.clearInterval(timerRef.current); const chars = "01X_#/$%"; let frame = 0; timerRef.current = window.setInterval(() => { const progress = frame / 10; setDisplay(text.split("").map((char, index) => char === " " || char === "\n" ? char : index / text.length < progress ? char : chars[Math.floor(Math.random() * chars.length)]).join("")); frame += 1; if (frame > 10 && timerRef.current) { window.clearInterval(timerRef.current); timerRef.current = null; setDisplay(text); } }, 30); };
  useEffect(() => () => { if (timerRef.current) window.clearInterval(timerRef.current); }, []);
  return <span className={`scramble-heading whitespace-pre-line ${className}`} tabIndex={0} aria-label={text} onMouseEnter={run} onFocus={run}>{display}</span>;
}

