      {state === "pass" && <div className="success-reveal space-y-5"><div className="relative overflow-hidden rounded-2xl border border-[#f2d18a]/55 bg-gradient-to-br from-[#4f3a18] via-[#1c1710] to-[#0b0d12] p-8 text-center shadow-[0_0_42px_rgba(201,151,62,.16)]"><div className="absolute right-6 top-6 opacity-80"><img onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = "https://fortrexfx-lwqfvhpi.manus.space/manus-storage/fortrex-crown-clean_eedb458b.png"; }} src="/manus-storage/fortrex-crown-clean_eedb458b.png" alt="FORTREX crown" className="brand-crown-mark" /></div><div className="mb-8 text-[10px] font-bold uppercase tracking-[.24em] text-[#f2d18a]">FORTREX FX / EARLY ACCESS</div><div className="display welcome-message text-4xl font-bold text-[#fff7e6]">Welcome, {welcomeName}.</div><p className="mx-auto mt-4 max-w-sm text-sm leading-7 text-[#d8cba9]">The first message will find you when Fortrex is ready to be seen.</p><div className="transmission-glow success-pulse mt-8 flex flex-col items-center gap-3 rounded-xl border border-[#f2d18a]/24 bg-[#c9973e]/[.06] px-5 py-4 text-center"><div className="flex items-center gap-2 text-sm font-semibold text-[#fff7e6]"><Check size={15} className="text-[#f2d18a]" /> Encrypted transmission received</div><div className="font-mono text-xs uppercase tracking-[.16em] text-[#c9973e]">Next reveal in {countdownLabel}</div></div></div><div className="rounded-xl border border-[#f2d18a]/14 bg-white/[.025] p-5 text-center"><div className="mb-2 flex items-center justify-center gap-2 text-sm font-semibold text-[#fff7e6]"><Radio size={15} className="text-[#c9973e]" /> Keep Fortrex close</div><p className="text-sm leading-6 text-[#a99b7a]">Watch your inbox. The next reveal will not be public for long.</p></div><div className="success-actions grid gap-3 sm:grid-cols-3"><button onClick={copyInviteLink} className="secondary-cta flex min-h-12 items-center justify-center gap-2 rounded-full px-4 py-3 text-xs font-bold uppercase tracking-[.1em]"><Copy size={15} /> Copy Invite</button><button onClick={shareStatus} className="secondary-cta material-submit flex min-h-12 items-center justify-center gap-2 rounded-full px-4 py-3 text-xs font-bold uppercase tracking-[.1em]"><Share2 size={15} /> Share Status</button><button onClick={exploreMore} className="material-nav-item crystal-cta primary-cta flex min-h-12 w-full items-center justify-center gap-2 rounded-full px-4 py-3 text-xs font-bold uppercase tracking-[.1em]">Explore More <ChevronRight size={15} /></button></div></div>}
