function PolicySheet({ kind, onClose }: { kind: "terms" | "privacy"; onClose: () => void }) {
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); }; document.body.style.overflow = "hidden"; window.addEventListener("keydown", onKeyDown); return () => { document.body.style.overflow = ""; window.removeEventListener("keydown", onKeyDown); }; }, [onClose]);
  const isTerms = kind === "terms";
  return <div className="policy-backdrop" role="presentation" onMouseDown={onClose}><section className="policy-sheet p-6 sm:p-8" role="dialog" aria-modal="true" aria-labelledby="policy-title" onMouseDown={(event) => event.stopPropagation()}><div className="mb-6 flex items-start justify-between gap-5"><div><SectionKicker>{isTerms ? "Legal / terms" : "Legal / privacy"}</SectionKicker><h2 id="policy-title" className="display text-3xl font-bold text-[#fff7e6]">{isTerms ? "Terms of Service" : "Privacy Policy"}</h2></div><button onClick={onClose} className="text-2xl text-[#a99b7a] hover:text-[#fff7e6]" aria-label={`Close ${isTerms ? "Terms of Service" : "Privacy Policy"}`}>×</button></div><div className="space-y-5 text-sm leading-7 text-[#b9ad91]">{isTerms ? <><p>Fortrex FX is preparing an upcoming product experience for traders who recognize meaningful opportunities early. This page is a pre-launch registration point, not a complete description of the product.</p><p>The details behind the Fortrex experience will be shared in stages with people on the early access list. Registration does not represent a promise of access to every future feature or outcome.</p><p>Review the final terms, eligibility requirements, and launch communications when they are published before taking action.</p></> : <><p>We collect the information needed to place you on the early access list, send launch communications, and understand interest in Fortrex.</p><p>Only submit information you are comfortable sharing. The final privacy notice will explain retention, deletion, security, and third-party processing before public launch.</p><p>We will update this page as the Fortrex experience moves from early access to public release.</p></>}</div><button onClick={onClose} className="primary-cta mt-8 rounded-full px-5 py-3 text-xs font-bold uppercase tracking-[.12em]">Return to Fortrex</button></section></div>;
}

type ContactModalProps = { message: string; onMessageChange: (value: string) => void; mailto: string; onClose: () => void };

function ContactModal({ message, onMessageChange, mailto, onClose }: ContactModalProps) {
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);

  return <div className="contact-backdrop" role="presentation" onMouseDown={onClose}><section className="contact-dialog glass gold-border" role="dialog" aria-modal="true" aria-labelledby="contact-title" onMouseDown={(event) => event.stopPropagation()}><div className="mb-5 flex items-start justify-between gap-4"><div><div className="text-[10px] font-bold uppercase tracking-[.22em] text-[#c9973e]">Fortrex / Support</div><h2 id="contact-title" className="display mt-2 text-3xl font-bold text-[#fff7e6]">Contact Us</h2></div><button type="button" onClick={onClose} className="modal-close text-[#a99b7a] hover:text-[#fff7e6]" aria-label="Close Contact Us">×</button></div><p className="text-sm leading-6 text-[#a99b7a]">Send a message to the Fortrex support desk and keep the subject concise so the right person can respond.</p><label className="mt-5 block text-left"><span className="mb-2 block text-xs font-semibold uppercase tracking-[.14em] text-[#a99b7a]">Your message</span><textarea value={message} onChange={(event) => onMessageChange(event.target.value)} maxLength={600} rows={5} placeholder="How can we help?" className="contact-message-input w-full rounded-xl px-4 py-3 text-sm text-[#fff7e6] outline-none placeholder:text-[#766c57]" /></label><div className="mt-2 text-right text-[11px] text-[#766c57]">{message.length}/600</div><div className="mt-5 grid gap-3 sm:grid-cols-2"><button type="button" onClick={onClose} className="secondary-cta rounded-full px-5 py-3 text-xs font-bold uppercase tracking-[.12em]">Cancel</button><a href={mailto} onClick={onClose} className="primary-cta flex items-center justify-center rounded-full px-5 py-3 text-xs font-bold uppercase tracking-[.12em]">Open email</a></div></section></div>;
}

